const characterFacts: Record<string, { faction: string; story: string; element: string; weapon: string }> = {
  "Albedo": { faction:"the Knights of Favonius' Investigation Team", story:"An alchemical prodigy created through Khemia by the master alchemist Rhinedottir, Albedo serves as the Knights of Favonius' Chief Alchemist while quietly tracing the boundary of his own artificial existence — wondering whether the life he holds is real, and whether the answer matters.", element:"Geo", weapon:"sword" },
  "Amber": { faction:"Mondstadt's Outrider corps", story:"The last remaining Outrider of the Knights of Favonius and the first to greet the Traveler at the city gates. Amber protects Mondstadt's outer reaches with optimism, her companion Baron Bunny and sharp situational awareness that belies her cheerful exterior.", element:"Pyro", weapon:"bow" },
  "Barbara": { faction:"the Church of Favonius", story:"Mondstadt's beloved deaconess and idol who heals the city's sick while quietly managing the gap between the Church's religious teachings and her sister Jean's secular authority. Barbara's faith in people is absolute, and her desire to help them extends far beyond song and prayer.", element:"Hydro", weapon:"catalyst" },
  "Bennett": { faction:"the self-led Benny's Adventure Team", story:"Mondstadt's most enthusiastic adventurer and its unluckiest — his bad fortune follows him everywhere and has driven away every companion except Paimon's occasional sympathy. Bennett refuses to be defined by misfortune and continues exploring, convinced that luck is simply an opportunity waiting in the wrong direction.", element:"Pyro", weapon:"sword" },
  "Dahlia": { faction:"the Church of Favonius", story:"A devoted member of Mondstadt's Church of Favonius who supports the established religious community and works alongside Barbara in service to the city. Dahlia represents the quieter, administrative side of faith — steady, organized and committed to Mondstadt's social fabric.", element:"Hydro", weapon:"sword" },
  "Diluc": { faction:"Dawn Winery and Mondstadt's unofficial defense network", story:"Once the youngest Knight of Favonius to achieve the rank of Captain, Diluc left the organization after a confrontation with both a Fatui operative and the institution's unwillingness to hold itself accountable. He now operates outside the law — gathering intelligence, funding operations and protecting Mondstadt through a network he built entirely on his own terms.", element:"Pyro", weapon:"claymore" },
  "Diona": { faction:"The Cat's Tail", story:"A bartender at The Cat's Tail who despises alcohol on principle and yet is inexplicably talented at mixing drinks. Diona's goal has always been to ruin wine's reputation by making cocktails so terrible that people stop drinking — but her Cryo talent produces drinks so perfect that even her enemies become loyal customers.", element:"Cryo", weapon:"bow" },
  "Eula": { faction:"the Knights of Favonius", story:"Descended from the Lawrence Clan — the former ruling family of Mondstadt that enslaved its people before the God of Freedom intervened — Eula has spent her life fighting to separate her name from that legacy while serving the very city her family once oppressed. Her battlefield intensity is legendary, and her grudge list is famously long.", element:"Cryo", weapon:"claymore" },
  "Fischl": { faction:"the Adventurers' Guild", story:"An investigator who presents herself as Fischl von Luftschloss Narfidort, Prinzessin der Verurteilung — a dramatic persona she built around her love of fantasy literature. Behind the affectation, Fischl carries a genuine and unexplained bond with her familiar Oz, an Electro crow whose origins connect to something far older than any role she has invented for herself.", element:"Electro", weapon:"bow" },
  "Jean": { faction:"the Knights of Favonius", story:"Acting Grand Master of the Knights of Favonius and the person who keeps Mondstadt's governing institution functional on a daily basis. Jean combines genuine diplomatic skill with an exhausting personal sense of duty — she rarely rests, rarely delegates and rarely admits that carrying an entire nation's governance on one person's shoulders might be unsustainable.", element:"Anemo", weapon:"sword" },
  "Kaeya": { faction:"the Knights of Favonius", story:"The Knights' Cavalry Captain who projects relaxed, unhurried charm in every interaction while maintaining information and plans that few people around him fully understand. Kaeya came to Mondstadt as a child with a secret mission from Khaenri'ah — a mission he has since set aside, though the history it represents still shapes who he is and what he is willing to protect.", element:"Cryo", weapon:"sword" },
  "Klee": { faction:"the Knights of Favonius", story:"The daughter of the renowned adventurer Alice, Klee was left in the Knights of Favonius' care while her mother pursues expeditions across Teyvat. As the Spark Knight, Klee's approach to obstacles, wildlife and fishing is identical: explosives. Her confinement to the Knights' prison library is a recurring occupational consequence.", element:"Pyro", weapon:"catalyst" },
  "Lisa": { faction:"Mondstadt's library", story:"Mondstadt's librarian and a former prodigy of the Sumeru Akademiya who chose a quieter life after witnessing what the institution's most demanding intellectual path actually costs. Lisa is deeply perceptive, selectively helpful and entirely aware of far more than she chooses to act upon — a trait that makes her as valuable as it makes her mysterious.", element:"Electro", weapon:"catalyst" },
  "Mika": { faction:"the Knights of Favonius' reconnaissance unit", story:"A cartographer and logistics specialist for the Knights' expeditions whose detailed field maps and careful planning keep teams safe in Mondstadt's most dangerous territory. Mika is methodical, quietly confident in specialized skills and tends to underestimate how much his preparation actually contributes to successful missions.", element:"Cryo", weapon:"polearm" },
  "Mona": { faction:"Mondstadt's independent astrologers", story:"A hydro astrologist who reads fate in the stars with genuine accuracy and an independent methodology that the larger astrological community finds difficult to categorize. Mona is chronically broke because she refuses to commercialize her gift for people who want comfortable predictions rather than true ones, and she is too proud to admit that her poverty is a choice.", element:"Hydro", weapon:"catalyst" },
  "Razor": { faction:"Wolvendom", story:"A young man raised by wolves in Wolvendom after being abandoned as a child, Razor lives on the edge between human and wild — understanding loyalty, pack hierarchy and instinct far more naturally than social convention or language. His connection to Fischl and other humans slowly draws him toward the civilization he never had, one friendship at a time.", element:"Electro", weapon:"claymore" },
  "Rosaria": { faction:"the Church of Favonius", story:"A member of the Church of Favonius whose methods have almost nothing to do with religious doctrine and almost everything to do with direct action against criminals operating inside Mondstadt. Rosaria works at night, pursues targets without institutional permission and maintains a past that the Church has decided it prefers not to look at too closely.", element:"Cryo", weapon:"polearm" },
  "Sucrose": { faction:"Mondstadt's alchemy team", story:"A bio-alchemist and Albedo's primary assistant whose research focuses on the fundamental particles of life and the question of whether alchemy can illuminate why living things exist at all. Sucrose is shy in social settings and intensely focused in the laboratory — a person for whom scientific curiosity is the clearest form of communication she has.", element:"Anemo", weapon:"catalyst" },
  "Venti": { faction:"Mondstadt and the Four Winds", story:"The bard known as Venti is Barbatos, the Anemo Archon and the weakest of the Seven — by choice. After a mortal friend inspired the idea of a nation built on freedom, Barbatos shaped Mondstadt around that principle and has spent the ages since living among its people rather than above them, composing songs and refusing the comfort of unearned divine authority.", element:"Anemo", weapon:"bow" },
  "Baizhu": { faction:"Bubu Pharmacy", story:"The proprietor of Liyue Harbor's Bubu Pharmacy who carries an incurable illness, a serpent familiar named Changsheng and an ongoing philosophical negotiation with the value of life. Baizhu treats patients with genuine skill while running private research into prolonged existence — driven partly by compassion and partly by his own situation with time.", element:"Dendro", weapon:"catalyst" },
  "Beidou": { faction:"the Crux Fleet", story:"The uncrowned queen of the Crux Fleet who built her reputation through single combat against sea monsters and maintains it through fiercely independent maritime operations. Beidou commands loyalty through direct leadership and personal capability rather than institutional rank — the kind of authority that follows someone because they want to, not because they must.", element:"Electro", weapon:"claymore" },
  "Chongyun": { faction:"a spirit-exorcising independent practice", story:"An exorcist whose body carries such an abundance of yang energy that all the ghosts and spirits he is supposed to exorcise simply flee before he arrives — a professional problem he compensates for by training with ice-based techniques that cool his energy and let him actually encounter the supernatural he dedicates his life to combating.", element:"Cryo", weapon:"claymore" },
  "Gaming": { faction:"Yip family's Wushou dancers", story:"A freight deliveryman who maintains his family's tradition of Wushou dancing — a martial art and performance tradition central to Liyue's festivals — alongside an entirely practical career hauling goods across the nation. Gaming navigates the tension between a beloved heritage and a father who finds no value in it, refusing to give up either.", element:"Pyro", weapon:"claymore" },
  "Ganyu": { faction:"the Liyue Qixing", story:"A half-human, half-Qilin Adeptus who has served as secretary and liaison between the Liyue Qixing and the Adepti for three thousand years. Ganyu's centuries of mediating between divine and human expectations have left her deeply conscientious and quietly exhausted — a person who measures her worth in what she can do for others and rarely considers what she might want for herself.", element:"Cryo", weapon:"bow" },
  "Hu Tao": { faction:"Wangsheng Funeral Parlor", story:"The 77th Director of Wangsheng Funeral Parlor who understands death not as an endpoint but as a ceremony, a transition and a responsibility toward the people left behind. Hu Tao's theatrical humor is genuine rather than affected — she has thought about mortality more carefully than most people twice her age, and her comfort with it is the result of that thought rather than a performance.", element:"Pyro", weapon:"polearm" },
  "Keqing": { faction:"the Liyue Qixing", story:"The Yuheng of the Liyue Qixing who fundamentally disputes the idea that a nation should depend on its gods for governance. Keqing's work is built on the belief that people are capable of solving their own problems — and her frustration with Rex Lapis has driven her to become, arguably, the hardest-working and most effective reformer in Liyue's public administration.", element:"Electro", weapon:"sword" },
  "Lan Yan": { faction:"a Liyue weaving craft", story:"A weaver and artisan whose sharp observation of materials and techniques has become its own form of knowledge. Lan Yan has found independence through her craft — developing her own approach to Liyue's textile traditions and building a practice that answers to no guild or institution except her own standards.", element:"Anemo", weapon:"catalyst" },
  "Ningguang": { faction:"the Liyue Qixing", story:"The Tianquan of the Liyue Qixing who built her position from nothing and established the Jade Chamber as a physical expression of her authority over Liyue's economy. Ningguang is a pragmatist who makes decisions based on what actually works rather than what tradition or divine precedent recommends — a quality that makes her indispensable during Liyue's transition from Archon governance to self-determination.", element:"Geo", weapon:"catalyst" },
  "Qiqi": { faction:"Bubu Pharmacy", story:"A zombie who returned from the dead during a traumatic encounter with both an Adeptus and the Fatui and has since been cared for by Baizhu at Bubu Pharmacy. Qiqi's memory resets frequently, so she relies on notebooks, rituals and the people around her to maintain continuity. She is gentle, careful and entirely aware that her situation is unusual.", element:"Cryo", weapon:"sword" },
  "Shenhe": { faction:"Liyue's Adepti-connected community", story:"A woman raised in seclusion by the Adeptus Cloud Retainer after a traumatic childhood, trained in techniques that suppress the overwhelming divine power in her body. Shenhe's isolation has left her without ordinary emotional frameworks — she is not cold, but she approaches human relationships with the deliberate care of someone learning a language they never had the chance to grow up speaking.", element:"Cryo", weapon:"polearm" },
  "Xiangling": { faction:"Wanmin Restaurant", story:"The head chef of Wanmin Restaurant who approaches cooking as exploration — hunting rare ingredients in dangerous wilderness, experimenting with combinations that conventional cooks would never attempt and consistently producing results that defy what anyone thought Liyue's culinary traditions were capable of. Her familiar Guoba accompanies her on expeditions and occasionally contributes to dishes.", element:"Pyro", weapon:"polearm" },
  "Xiao": { faction:"the Vigilant Yaksha", story:"The last surviving member of the five Yaksha warriors summoned by Rex Lapis to fight the remnant gods of the Archon War, Xiao has spent millennia suppressing demonic karma from the countless enemies he has killed in Liyue's defense. The karmic pain is real and visible — he endures it alone and at a distance from ordinary mortals, knowing that proximity to him during his worst moments carries risk.", element:"Anemo", weapon:"polearm" },
  "Xingqiu": { faction:"the Guhua Clan", story:"The second son of the Feiyun Commerce Guild who maintains his family's public position through careful attention to appearances while privately practicing the chivalric traditions of the Guhua Clan and writing martial arts novels under a pen name. Xingqiu is a scholar, a swordsman and an enthusiastic practitioner of his own idealized fiction — sometimes with real consequences for the people around him.", element:"Hydro", weapon:"sword" },
  "Xinyan": { faction:"Liyue's rock and roll scene", story:"Liyue's one-person rock and roll movement who performs music the city's traditional community has no category for and refuses to modify her sound to fit expectations. Xinyan's performances are genuinely loud, visually intense and have caused minor structural incidents in several venues — an outcome she considers a measure of success rather than a problem.", element:"Pyro", weapon:"claymore" },
  "Yanfei": { faction:"Liyue's legal practice", story:"A legal adviser of half-Adeptus heritage who has memorized every contract, precedent and clause in Liyue's extensive legal tradition and uses that knowledge to represent ordinary citizens against institutions that assume ordinary people cannot afford to understand the law. Yanfei loves her work in a way that makes contracts feel, against all reasonable expectation, exciting.", element:"Pyro", weapon:"catalyst" },
  "Yaoyao": { faction:"the Adepti's student community", story:"A young girl studying under the guidance of Liyue's Adepti and presently working alongside Ganyu and Xiangling as she develops her own skill with Dendro medicine and herbal combat. Yaoyao has a gentle, earnest outlook and a natural talent for care — she approaches every situation, however dangerous, as an opportunity to help someone.", element:"Dendro", weapon:"polearm" },
  "Yelan": { faction:"Liyue's intelligence network", story:"An operative of Liyue's Ministry of Civil Affairs who works under enough cover identities that even the Qixing is not certain what her actual role is. Yelan investigates threats to Liyue from the inside — a position that requires her to know things she cannot officially know, using resources she does not officially have, in service of outcomes that are never officially attributed to her.", element:"Hydro", weapon:"bow" },
  "Yun Jin": { faction:"Yun-Han Opera Troupe", story:"Director of the Yun-Han Opera Troupe and one of Liyue's most celebrated performers in the guohan tradition, Yun Jin studies historical texts and composes original works while actively modernizing a form that risks becoming decorative rather than living. Her ambition is to keep guohan evolving without losing the craft that makes it worth preserving.", element:"Geo", weapon:"polearm" },
  "Zhongli": { faction:"the Wangsheng Funeral Parlor and former Archonhood", story:"Rex Lapis, the Geo Archon and oldest of the Seven, who chose to end his public divine rule and hand Liyue's governance to its own people. Now working as a consultant named Zhongli at Wangsheng Funeral Parlor, he navigates mortal life with genuine interest and an occasional blind spot for the fact that centuries of divine wealth left him with no practical sense of modern currency.", element:"Geo", weapon:"polearm" },
  "Arataki Itto": { faction:"the Arataki Gang", story:"An Oni of Hanamizaka who leads a gang composed of Mondstadt's most enthusiastic misfits and has built a neighborhood reputation around beetle sumo, loud challenges and the absolute refusal to feel shame about any of it. Itto is genuinely competitive, genuinely loyal and genuinely baffled by people who take social convention more seriously than friendship.", element:"Geo", weapon:"claymore" },
  "Gorou": { faction:"Watatsumi Army", story:"The general of Watatsumi Island's resistance forces who fought for Vision-bearers' rights against the Shogunate's decree with limited numbers, genuine strategy and total commitment to every soldier under his command. Gorou's leadership is built on the principle that people worth commanding are worth protecting, and that a general who does not live that principle has nothing to ask of their troops.", element:"Geo", weapon:"bow" },
  "Kaedehara Kazuha": { faction:"the Crux Fleet", story:"A wandering samurai of the disgraced Kaedehara clan who witnessed a close friend die under the Vision Hunt Decree — struck down trying to claim a fallen Vision — and has since carried his friend's Vision alongside his own grief and the blade of his family's dissolved tradition. Kazuha reads the wind, the emotions of people around him and the meaning of moments with a sensitivity that he has never found a reason to suppress.", element:"Anemo", weapon:"sword" },
  "Kamisato Ayaka": { faction:"the Yashiro Commission", story:"The Shirasagi Himegimi of the Kamisato household who represents the family in public ceremonies, cultural events and the quiet coordination of Inazuma's traditional community — while privately supporting the resistance against the Vision Hunt Decree and working to protect ordinary Inazumans from its consequences. Ayaka's public grace conceals both the loneliness of her position and the careful attention she pays to people she might not be allowed to openly befriend.", element:"Cryo", weapon:"sword" },
  "Kamisato Ayato": { faction:"the Yashiro Commission", story:"The head of the Kamisato Clan who manages the household's political position through commerce, alliance-building and extremely careful management of what other factions believe the Kamisatos want. Ayato's relaxed demeanor during tense situations is not indifference — it is the product of extensive preparation and a talent for understanding what other people are trying to accomplish well before they reveal it.", element:"Hydro", weapon:"sword" },
  "Kirara": { faction:"Komaniya Express", story:"A nekomata courier who approaches every delivery as a solemn professional obligation. Kirara's knowledge of Inazuma's roads, weather patterns and island-to-island routes is detailed enough to be valuable on its own, but what actually distinguishes her is the pride she takes in keeping every promise she makes to every client — a commitment that extends to genuinely dangerous situations without hesitation.", element:"Dendro", weapon:"sword" },
  "Kujou Sara": { faction:"the Tenryou Commission", story:"A tengu raised within the Tenryou Commission and trained to treat obedience to the Raiden Shogun as an absolute value — an upbringing that served her well until the Vision Hunt Decree required her to suppress Vision-bearers she had no personal cause to oppose. Sara's confrontation with the gap between loyalty and justice is not resolved quickly, and the resolution requires her to hold both simultaneously rather than discarding one.", element:"Electro", weapon:"bow" },
  "Kuki Shinobu": { faction:"the Arataki Gang", story:"Itto's deputy and the reason the Arataki Gang maintains any operational coherence at all. Shinobu holds academic qualifications in law, shrine practice and practical medicine — credentials she obtained partly to give herself options and partly because knowledge has always been her primary means of protection. She joined the gang by genuine choice and remains not because she lacks alternatives but because she has decided these people deserve someone capable of looking after them.", element:"Electro", weapon:"sword" },
  "Raiden Shogun": { faction:"Inazuma and the eternity decree", story:"Raiden Ei, the Electro Archon, governs Inazuma through a puppet body she created to administer the Vision Hunt Decree while she meditates in the Plane of Euthymia — a divine space where time and change cannot reach her. Ei's pursuit of eternity is rooted in the losses of the Archon War: she watched friends and siblings die and concluded that the only way to protect what she loves is to prevent it from changing at all. The Traveler's confrontation with her is ultimately a conversation about what protection means and whether stillness can be separated from death.", element:"Electro", weapon:"polearm" },
  "Sangonomiya Kokomi": { faction:"Watatsumi Island", story:"The Divine Priestess of Watatsumi Island who simultaneously leads the island's military strategy, its civil administration and its religious ceremonies — a workload she carries with careful preparation and the quiet awareness that her talent for strategy sometimes isolates her from the people she is protecting. Kokomi deliberately avoids cultivating personal fame, preferring outcomes to recognition.", element:"Hydro", weapon:"catalyst" },
  "Sayu": { faction:"the Shuumatsuban", story:"A ninja of the Shuumatsuban who is convinced that the secret to growing taller is to sleep as much as possible and has organized her entire professional life around protecting opportunities for rest. Sayu is genuinely capable — her stealth, speed and momentum-based combat reflect real discipline — but she prefers to conserve energy for missions and considers excessive wakefulness a poor use of a person's limited time.", element:"Anemo", weapon:"claymore" },
  "Shikanoin Heizou": { faction:"the Tenryou Commission", story:"A detective attached to the Tenryou Commission who solves cases through a combination of perceptive observation, intuitive reasoning and a congenital inability to accept institutional hierarchy as a reason to stop asking questions. Heizou is playful in manner and genuinely sharp in method — he treats investigations as puzzles to be enjoyed and colleagues' discomfort at his methods as a minor operational inconvenience.", element:"Anemo", weapon:"catalyst" },
  "Thoma": { faction:"the Kamisato Clan", story:"A Mondstadt-born retainer of the Kamisato household who built a life in Inazuma by earning genuine trust among communities that rarely extend it to foreigners. Thoma's ability to operate across Inazuma's factional divides — connecting the Kamisato interests to merchants, neighborhood leaders and anyone else who needs a reliable point of contact — makes him valuable in ways that go well beyond personal protection.", element:"Pyro", weapon:"polearm" },
  "Yae Miko": { faction:"Grand Narukami Shrine", story:"The Guuji of the Grand Narukami Shrine and a kitsune with a history that predates most of Inazuma's current institutions. Yae Miko manages the shrine, runs the Yae Publishing House, maintains her friendship with Ei through the Plane of Euthymia and periodically tests the limits of the Shogun's decision-making — not out of disloyalty but from a conviction that people, including gods, should be confronted with the consequences of their choices.", element:"Electro", weapon:"catalyst" },
  "Yoimiya": { faction:"Naganohara Fireworks", story:"The head of Naganohara Fireworks who inherited her father's workshop and has since turned it into the defining voice of Inazuma's summer celebration. Yoimiya designs each firework for a specific person — matching the light, the spread, the color and the duration to what she understands about who that person is and what they deserve to see in the sky on the best night of the year.", element:"Pyro", weapon:"bow" },
  "Yumemizuki Mizuki": { faction:"Aisa Bathhouse", story:"A practitioner who works at the Aisa Bathhouse and uses dream therapy to help clients examine stress, memory and the emotional material that ordinary life does not give people space to process. Mizuki's approach to dreams is simultaneously scientific and empathetic — she studies what the mind does when it is not performing and uses that knowledge to help people understand what they cannot access while awake.", element:"Anemo", weapon:"catalyst" },
  "Alhaitham": { faction:"the Sumeru Akademiya", story:"The Scribe of the Sumeru Akademiya who treats the institution as a resource rather than an authority and applies a strict personal standard of logical consistency to every decision he makes — including the decision to get involved in the crisis caused by the institution he works for. Alhaitham is not antisocial; he is specific about which conversations are worth having, and that specificity reads as coldness to people who have never had him decide their company was worth his time.", element:"Dendro", weapon:"sword" },
  "Candace": { faction:"Aaru Village", story:"The guardian of Aaru Village in Sumeru's desert who protects its people with a combination of genuine combat skill and an authority that derives entirely from personal commitment rather than institutional rank. Candace's golden eye marks her as a descendant of King Deshret's legacy — a heritage she carries honestly and uses as a point of connection rather than separation.", element:"Hydro", weapon:"polearm" },
  "Collei": { faction:"the Forest Rangers", story:"A young ranger who rebuilt her life and her sense of self after being used as a test subject by the Fatui for an experimental Archon Residue parasite called Dendro Archon's Seed. Collei came to Sumeru with no identity she trusted and gradually built one — through her work in the forest, her connections with Tighnari and Cyno and the daily practice of being a person rather than a victim.", element:"Dendro", weapon:"bow" },
  "Cyno": { faction:"the Matra", story:"The General Mahamatra of the Sumeru Akademiya — the head of the enforcement division responsible for investigating academic misconduct and illegal research. Cyno carries the power of the Hermanubis through his Vision and applies it with the gravity of someone who understands exactly how dangerous forbidden knowledge can be. His jokes are dreadful and he delivers them with the same composure he brings to everything else.", element:"Electro", weapon:"polearm" },
  "Dehya": { faction:"The Eremites", story:"A mercenary of the Eremites who has built a reputation for reliability and genuine combat strength in Sumeru's desert — where both are tested regularly. Dehya takes contracts she believes in and exits ones she does not, a standard that has cost her comfortable arrangements and produced better ones. Her loyalty to the people she actually works with is unconditional once extended.", element:"Pyro", weapon:"claymore" },
  "Dori": { faction:"the Sangemah Bay merchant network", story:"A traveling merchant whose supply network reaches from Sumeru's rainforest to its deepest desert and whose prices reflect the absolute maximum the market will support at any given moment. Dori's business philosophy is not exploitative by her own reckoning — she provides things people cannot get anywhere else and charges accordingly, which is simply commerce made honest.", element:"Electro", weapon:"claymore" },
  "Faruzan": { faction:"the Akademiya's Haravatat darshan", story:"A researcher who was sealed inside an ancient puzzle box during a field expedition one hundred years ago and emerged into a Sumeru that had advanced well past the technology she spent her career developing. Faruzan teaches what the current Akademiya barely recognizes as a coherent field, corrects students with minimal patience for ignorance and is privately still adjusting to the gap between the world she knew and the one she woke up in.", element:"Anemo", weapon:"bow" },
  "Kaveh": { faction:"Sumeru's architectural community", story:"An architect whose award-winning designs balance structural beauty with human proportion — the belief that a building should feel inhabitable by the people it serves, not simply impressive to those who have never entered it. Kaveh is in debt because he completed a commission at his own expense when the client could not pay, and he lives with Alhaitham because he has not found a way out of that situation that does not require compromising the principles that created it.", element:"Dendro", weapon:"claymore" },
  "Layla": { faction:"the Rtawahist darshan", story:"An astronomy student at the Rtawahist darshan who conducts serious research into Teyvat's celestial patterns while also experiencing a persistent sleepwalking phenomenon that produces Cryo constructs during her unconscious intervals. Layla is dedicated to her work and exhausted by her condition — she has trouble finishing her thesis because the part of her that does the best research apparently operates best when she is asleep.", element:"Cryo", weapon:"sword" },
  "Nahida": { faction:"Sumeru and the Akasha", story:"Lesser Lord Kusanali, the Dendro Archon of Sumeru, who has been confined in the Sanctuary of Surasthana by the Grand Sages for nearly five hundred years. Despite her isolation from the physical world, Nahida has observed Sumeru through its dreams and the Akasha System with patience and genuine care — developing a deep understanding of its people while they were taught to dismiss her as an inadequate god. When the Traveler reaches her, she finally has a way to act.", element:"Dendro", weapon:"catalyst" },
  "Nilou": { faction:"Zubayr Theater", story:"A dancer at Zubayr Theater in Sumeru City who preserves the original meaning of the Sabzeruz Festival — a celebration of Lesser Lord Kusanali that the Akademiya has gradually eroded into irrelevance. Nilou's performances carry genuine spiritual weight for the forest communities that the desert-based Akademiya tends to overlook, and her kindness toward people outside the city's academic circles makes her a rare bridge between Sumeru's divided communities.", element:"Hydro", weapon:"sword" },
  "Sethos": { faction:"Aaru Village", story:"A young man connected to Aaru Village whose knowledge of the desert's hidden history and willingness to test dangerous situations has made him an unconventional but valuable asset in Sumeru's ongoing investigation of King Deshret's legacy. Sethos operates with a lightness of manner that sometimes obscures how seriously he takes the weight of what he has inherited from the desert's past.", element:"Electro", weapon:"bow" },
  "Tighnari": { faction:"the Forest Rangers", story:"A scholar-ranger who leads the Forest Ranger station near Gandharva Ville and conducts field research into Sumeru's plant life, ecosystem health and the spread of Eleazar — a disease affecting forest communities whose etiology the Akademiya has not prioritized. Tighnari's directness is widely reported as bluntness; his former students generally describe it as the most useful feedback they ever received.", element:"Dendro", weapon:"bow" },
  "Wanderer": { faction:"the surviving puppets of Inazuma", story:"A puppet created from the remains of Raiden Ei's emotions and discarded when his fundamental flaw — the ability to feel — made him incompatible with his intended function. Having spent his existence under multiple identities, served the Fatui as Scaramouche and been elevated briefly to manufactured godhood, he now exists under a new name and the deliberate choice to build a life that belongs to himself rather than the history assigned to him.", element:"Anemo", weapon:"catalyst" },
  "Charlotte": { faction:"The Steambird", story:"A reporter for The Steambird who pursues every story in Fontaine with the conviction that the truth is worth discomfort — her own and everyone else's. Charlotte's investigative instincts are good, her Kamera work is reliable and her willingness to follow a lead into genuinely dangerous situations reflects a professional commitment that sometimes outruns her practical preparation.", element:"Cryo", weapon:"catalyst" },
  "Chevreuse": { faction:"Fontaine's Special Security and Surveillance Patrol", story:"A captain of Fontaine's Special Security and Surveillance Patrol who investigates the illegal military application of Fontaine's distinctive technology — a jurisdiction that places her between the official justice system and the people who fund it. Chevreuse is thorough, precise and genuinely committed to accountability that extends upward in a hierarchy as well as downward.", element:"Pyro", weapon:"polearm" },
  "Chiori": { faction:"Chioriya Boutique", story:"An Inazuman designer who established Chioriya Boutique in Fontaine and built a reputation for fashion that answers to her own standards rather than any client's comfort. Chiori's designs reflect a philosophy she applies as strictly to herself as to her work: every element must justify its presence, and sentiment is not justification. The boutique is a success. Its owner remains difficult to know.", element:"Geo", weapon:"sword" },
  "Clorinde": { faction:"Fontaine's Champion Duelists", story:"Fontaine's Champion Duelist who serves the Court as an official representative of its dueling traditions — a role that requires her to fight, judge and sometimes absorb outcomes that official justice cannot directly address. Clorinde carries a contract with a demon that grants her power and demands a cost she has calculated and accepted. Her commitment to Fontaine's law is real, and so is her willingness to follow that law to uncomfortable places.", element:"Electro", weapon:"sword" },
  "Emilie": { faction:"Fontaine's perfume atelier", story:"A perfumer whose work involves forensic analysis of scent as a record of events — decomposition rates, chemical traces and the memory of materials that remain after everything else has changed. Emilie approaches fragrance as documentation and applies the same rigor to creating perfumes that preserve a precise emotional memory as she does to reading a crime scene.", element:"Dendro", weapon:"polearm" },
  "Escoffier": { faction:"Fontaine's culinary world", story:"A chef whose technique is exacting and whose respect for ingredients exceeds her patience for shortcuts. Escoffier's cuisine reflects a Fontainian belief that justice extends to what is put on the table: the right ingredient, properly prepared, is both technically correct and genuinely satisfying — an alignment that bad cooking breaks and that she considers a professional obligation to maintain.", element:"Cryo", weapon:"polearm" },
  "Freminet": { faction:"the House of the Hearth", story:"A deep-sea diver and mechanic raised in the House of the Hearth alongside Lyney and Lynette, Freminet finds more comfort among machinery and sea creatures than in human company. His diving work and his relationship with his mechanical companion Pers reflect a sensibility that processes the world through repair, maintenance and the particular silence available below Fontaine's waters.", element:"Cryo", weapon:"claymore" },
  "Furina": { faction:"Fontaine's former divine role", story:"Given the role of Focalors and left to perform it without divine power for five hundred years, Furina maintained Fontaine's court, withstood its trials and endured public mockery as an apparently fallible god — all to satisfy the conditions of a plan she was never permitted to explain. The plan worked. The prophecy was defeated. Furina survived to discover that the performance she spent her entire life perfecting was the most selfless thing anyone in Teyvat has ever done alone.", element:"Hydro", weapon:"sword" },
  "Lynette": { faction:"the House of the Hearth", story:"Lyney's assistant and sibling, raised in the House of the Hearth alongside him. Lynette's stage role is support and misdirection — she is exceptionally good at both. Her personal communication is minimal, her loyalty to her family is absolute and the gap between how much she observes and how much she reveals is wide enough to be unsettling to people who mistake quiet for inattention.", element:"Anemo", weapon:"sword" },
  "Lyney": { faction:"the House of the Hearth", story:"A stage magician who performs Fontaine's most popular illusion acts while simultaneously operating as one of Arlecchino's most effective field agents for the House of the Hearth. Lyney's charm is genuine — he actually enjoys performance — but it is also precisely calibrated for situations where being liked is the first step toward being trusted and being trusted is the first step toward getting something done.", element:"Pyro", weapon:"bow" },
  "Navia": { faction:"Spina di Rosula", story:"The leader of Spina di Rosula who inherited the position after her father was condemned by Fontaine's court on falsified evidence. Navia's determination to clear her father's name and restore her organization's standing has shaped her into someone who takes personal responsibility for everyone under her protection — not because the role demands it but because she has decided that is what the role should mean.", element:"Geo", weapon:"claymore" },
  "Neuvillette": { faction:"Fontaine's court", story:"The Iudex of Fontaine whose composed judicial authority has governed the Court of Fontaine for centuries. Neuvillette is the reincarnation of the Hydro Dragon Sovereign — one of the original rulers of Teyvat before the Archons — who has been slowly reclaiming the authority lost during the ancient conflict. His visible grief at Fontaine's sorrows is not performance: the rain that falls when he cries is real, and the connection to Fontaine's waters runs through him in ways neither he nor anyone around him initially understood.", element:"Hydro", weapon:"catalyst" },
  "Sigewinne": { faction:"Meropide's infirmary", story:"The head nurse of Meropide's infirmary who cares for prisoners, researches medical treatment in conditions of limited supply and maintains a genuinely affectionate outlook toward everyone in the facility — including people who have done things that would justify the opposite. Sigewinne's medical curiosity and her tendency to treat experiments as naturally interesting rather than ethically complicated have occasionally alarmed her colleagues.", element:"Hydro", weapon:"bow" },
  "Wriothesley": { faction:"Meropide", story:"The Duke of Meropide who administers the underwater prison facility with strict discipline and a private commitment to ensuring that the institution does not become an excuse for cruelty. Wriothesley was himself convicted as a child and has lived in Meropide long enough to understand what it does to people — which is precisely why he runs it the way he does.", element:"Cryo", weapon:"catalyst" },
  "Chasca": { faction:"Natlan's Flower-Feather Clan", story:"A Sky-People rider who serves as a peacekeeping force between Natlan's tribes and carries the history of a conflict she was raised inside rather than by her own choices. Chasca's work now reflects a deliberate reorientation — from inherited violence toward mediation and protection — made credible by the fact that she understands both sides of every boundary she is asked to enforce.", element:"Anemo", weapon:"bow" },
  "Citlali": { faction:"the Masters of the Night-Wind", story:"A practitioner of Natlan's ancient rite traditions who carries knowledge that she deliberately frames as eccentricity to prevent people from treating her as an authority when what she actually is is a resource. Citlali's ritecraft is genuine and her understanding of the Night Kingdom's supernatural geography is deeper than she reveals — a depth she protects through deflection because too much attention to its source would make it less effective.", element:"Cryo", weapon:"catalyst" },
  "Iansan": { faction:"the Collective of Plenty", story:"A warrior of the Collective of Plenty whose training in physical discipline and strength-based combat reflects Natlan's tradition of service through personal capability. Iansan's approach to community is direct — she demonstrates commitment through action and expects the same from people she trains alongside, a standard she applies equally to herself and everyone around her.", element:"Electro", weapon:"polearm" },
  "Ifa": { faction:"Natlan's saurian community", story:"A healer and researcher who works between Natlan's tribal communities and its saurian wildlife, treating injuries and studying the physiological relationship between saurians and the Sacred Flame. Ifa's approach to both species is empirical and compassionate — she observes carefully, treats without assumptions and brings the same standard of care to a wounded saurian that she applies to any human patient.", element:"Anemo", weapon:"catalyst" },
  "Kachina": { faction:"the Children of Echoes", story:"A young member of the Children of Echoes tribe who undertakes the Pilgrimage to prove her courage and competence despite being consistently underestimated by people who mistake her size and uncertainty for a lack of readiness. Kachina's strength is not primarily physical — it is her willingness to continue after the first failure, the second and the third, until the task is done.", element:"Geo", weapon:"polearm" },
  "Kinich": { faction:"Huitztlan", story:"A hunter from Huitztlan who operates through contracts and accompanies the Traveler through Natlan's conflicts with a pragmatism that makes him useful without requiring him to hold any strong investment in the outcome. His companion Ajaw complicates this arrangement regularly. Kinich is more involved in Natlan's situation than his detachment suggests, but acknowledging that involvement would require a conversation he has not decided to have yet.", element:"Dendro", weapon:"claymore" },
  "Mavuika": { faction:"Natlan and the Pyro Archon", story:"The Pyro Archon of Natlan who carries the Sacred Flame on behalf of the tribes, mediates between their competing traditions and has known for some time that the current cycle of the Night Kingdom war will require a final cost she is prepared to pay. Mavuika's warmth toward the people of Natlan is not performance — it is the product of centuries spent in genuine relationship with them, and it coexists with a clear-eyed understanding of what protecting them has always required.", element:"Pyro", weapon:"claymore" },
  "Mualani": { faction:"the People of the Springs", story:"A guide and water spirit of the People of the Springs who moves through Natlan's waterways with a contagious enthusiasm for both the journey and the company. Mualani's warmth is real, her knowledge of the region is extensive and her ability to make dangerous crossings feel like adventures rather than ordeals has made her essential to both tourism and emergency coordination across Natlan's tribal territories.", element:"Hydro", weapon:"catalyst" },
  "Ororon": { faction:"the Masters of the Night-Wind", story:"A member of the Masters of the Night-Wind who moves between the tribe's public community and its deeper connections to the Night Kingdom's defense with a discretion that reflects genuine understanding of what the Night Kingdom is. Ororon's isolation from ordinary social life is not misanthropy — it is the consequence of knowing things about Natlan's supernatural geography that make ordinary conversation feel imprecise.", element:"Electro", weapon:"bow" },
  "Varesa": { faction:"the Collective of Plenty", story:"A member of the Collective of Plenty whose athletic power and competitive enthusiasm make her an immediately visible presence in any challenge, contest or crisis. Varesa's love of food is as genuine as her love of competition — she approaches both as ways of connecting with people and experiencing a world that she finds straightforwardly excellent.", element:"Electro", weapon:"catalyst" },
  "Xilonen": { faction:"the Nanatzcayan craftsmen", story:"A master smith of Nanatzcayan who forges weapons, armor and the named artifacts that Natlan's heroes carry into the Night Kingdom. Xilonen's metallurgical knowledge extends beyond technique into the spiritual dimension of Natlan's materials — the Sacred Flame is not simply a source of heat in her forge but a collaborator in what gets made and what it is made to do.", element:"Geo", weapon:"sword" },
  "Aino": { faction:"Clink-Clank Krumkake Craftshop", story:"A young mechanic and inventor at Nod-Krai's Clink-Clank Krumkake Craftshop who approaches the region's unusual frontier problems with practical engineering and genuine curiosity. Aino's perspective on Nod-Krai's competing factions and supernatural phenomena is shaped by proximity rather than ideology — she has seen what the moon does to the region's landscape and has built machines accordingly.", element:"Hydro", weapon:"claymore" },
  "Flins": { faction:"the Lightkeepers", story:"A Lightkeeper stationed at one of Nod-Krai's northern frontier posts who monitors the region's supernatural phenomena and maintains the defensive infrastructure that has kept its communities separated from whatever the region's ancient history contains. Flins connects the Traveler to both the Lightkeepers' institutional knowledge and the personal history of living on a frontier where the boundary between ordinary danger and something much older is never entirely clear.", element:"Electro", weapon:"polearm" },
  "Ineffa": { faction:"Nod-Krai's independent mechanics", story:"A mechanic and designer working independently in Nod-Krai whose work intersects the region's technological needs with its supernatural realities. Ineffa's designs reflect a practical accommodation of the fact that Nod-Krai's environment does not behave like other nations — the moon's influence on materials, weather and geography requires engineering that accounts for variables other craftsmen do not encounter.", element:"Electro", weapon:"polearm" },
  "Jahoda": { faction:"Nod-Krai's frontier factions", story:"A resourceful figure who moves between Nod-Krai's competing communities with practical skill and an understanding of the region's factional landscape built from direct experience rather than external observation. Jahoda's value to the Traveler in Nod-Krai is knowledge that cannot be found in any archive — the kind accumulated by someone who has lived inside the region's contradictions long enough to know where the pressure points are.", element:"Anemo", weapon:"bow" },
  "Lauma": { faction:"the Frostmoon Scions", story:"The emissary and leader of the Frostmoon Scions — a community in Nod-Krai organized around lunar rituals and the protection of moon relics that outside powers have increasingly targeted. Lauma defends her community's traditions from exploitation while navigating pressure from the Fatui and the broader destabilization that the Song of the Welkin Moon crisis brings to Nod-Krai's fragile autonomy.", element:"Dendro", weapon:"catalyst" },
  "Nefer": { faction:"Nod-Krai's moon-linked factions", story:"A figure connected to Nod-Krai's moon-linked communities whose knowledge of the region's hidden factions and lunar heritage makes them a valuable and carefully managed presence in the area's shifting politics. Nefer moves through Nod-Krai's uncertainty with an understanding of what the moon relics actually represent — not simply power, but a responsibility toward something that predates the current age.", element:"Dendro", weapon:"catalyst" },
  "Illuga": { faction:"Nod-Krai's frontier forces", story:"A fighter and organizer who connects Nod-Krai's local defensive communities to the broader effort of protecting the region's borders during the Song of the Welkin Moon crisis. Illuga's work is coordination rather than command — bringing together people with different affiliations and conflicting interests around the shared recognition that the region's current threat requires a collective response.", element:"Geo", weapon:"polearm" },
  "Linnea": { faction:"Nod-Krai's local community", story:"A resident of Nod-Krai whose personal story sits within the larger conflict between outside powers competing over the region's legacy. Linnea represents the human dimension of Nod-Krai's crisis — the people whose lives are shaped by events they did not choose and whose futures depend on outcomes that larger factions are deciding without them.", element:"Hydro", weapon:"bow" },
  "Columbina": { faction:"Nod-Krai's moon-linked factions", story:"A former Fatui Harbinger whose connection to the moon, the Abyss and forces that extend beyond Snezhnaya's known operations makes her one of the most significant presences in Nod-Krai's story. Columbina's nature, motivations and the full scope of her power remain deliberately obscured — she operates at the edge of what the archive can confirm and the beginning of something the Traveler has not yet fully encountered.", element:"Hydro", weapon:"catalyst" },
  "Tsaritsa": { faction:"Snezhnaya and the Fatui", story:"The Cryo Archon of Snezhnaya who directs the Fatui toward the collection of Gnoses from every Archon in Teyvat and the execution of a plan that positions itself in opposition to Celestia's established divine order. The Tsaritsa's transformation from a god described in older records as deeply loving into the architect of Teyvat's most aggressive anti-celestial campaign reflects a change whose cause the Traveler approaches slowly, from the outside, through the actions of the people she has made responsible for carrying it out.", element:"Cryo", weapon:"unknown" },
  "Arlecchino": { faction:"the Fatui Harbingers", story:"The Fourth Fatui Harbinger who leads the House of the Hearth — an orphanage and training operation that raises Fatui operatives from childhood through a system of Blood-Debt that obligates every member until the debt is cleared. Arlecchino's goals are not identical to the Fatui's conventional interests, her method of running the House is distinct from what the institution's history suggests, and her understanding of what she is building differs in ways that become clear only when the Traveler encounters what the House of the Hearth's members will actually do for her.", element:"Pyro", weapon:"polearm" },
  "Tartaglia": { faction:"the Fatui Harbingers", story:"The Eleventh Fatui Harbinger known as Childe whose defining characteristic is a desire for combat that has shaped his entire history — including the discovery of the Foul Legacy fighting style in an Abyssal space he entered as a child and was changed by permanently. Tartaglia's campaigns in Liyue, Inazuma and beyond are not simply Fatui operations; they are his own search for opponents and situations that can fully engage what he has become.", element:"Hydro", weapon:"bow" },
  "Sandrone": { faction:"the Fatui Harbingers", story:"A Fatui Harbinger associated with Snezhnayan automaton technology and the Fatui's most sophisticated mechanical research programs. Sandrone's work represents the intersection of the Tsaritsa's campaign with the kind of technological capability that does not require elemental power — a dimension of the Fatui's reach that sits apart from the Harbingers who operate through direct combat and political influence.", element:"unknown", weapon:"mechanical construct" },
  "Odette": { faction:"Snezhnayan society", story:"A Snezhnayan figure whose identity and role in the nation's story will become clear through the Traveler's journey into Snezhnaya. Odette's connection to Snezhnayan society represents one of the human dimensions of a nation that tends to be understood primarily through its Fatui infrastructure and the Tsaritsa's political project.", element:"Cryo", weapon:"unknown" },
  "Danica": { faction:"Snezhnayan society", story:"A Snezhnayan character connected to the human communities living within the Cryo nation's permanent winter. Danica's role in the Traveler's journey through Snezhnaya reflects the experience of ordinary life inside a nation governed by an Archon pursuing objectives that her citizens understand, at most, partially.", element:"Cryo", weapon:"unknown" },
  "Alyosha": { faction:"Snezhnayan society", story:"A resident of Snezhnaya who serves as one of the Traveler's first genuine human connections inside the Cryo nation — someone whose knowledge of local communities, Fatui infrastructure and the gap between official Snezhnayan life and its actual human texture helps the Traveler navigate a nation where most things of importance are not visible from the outside.", element:"Cryo", weapon:"sword" },
  "Vesna": { faction:"Snezhnayan society", story:"A human figure inside Snezhnaya's political landscape whose perspective on the Tsaritsa's project and the Fatui's presence in the nation represents the experience of people who live under a system designed around goals that are not primarily theirs.", element:"Cryo", weapon:"unknown" },
  "Vodyanitsa": { faction:"Snezhnayan folklore", story:"A figure tied to Snezhnayan folklore and the nation's deep mythological traditions — the stories that exist beneath official Fatui accounts and the Tsaritsa's political history, rooted in the land, the winter and the older Cryo spirits that Snezhnayan communities have always known.", element:"Cryo", weapon:"unknown" }
};
function slug(name: string) {
  return specialIds[name] ?? name.toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
}

const palette = ["#78A6A0","#C9A84C","#9A78C7","#A3C85C","#62BBD2","#EE7B35","#91B5C9","#BBD4E5","#5077A8"];

const regionLore: Record<string, string> = {
  "Mondstadt": "Mondstadt is the City of Freedom, protected by the ideals of the Anemo Archon Barbatos and watched over from the Knights of Favonius.",
  "Liyue": "Liyue is the nation of contracts, where merchants, Adepti and the Geo Archon have shaped a harbor society founded on mutual obligation.",
  "Inazuma": "Inazuma is the nation of eternity, an archipelago of tradition, resistance and ambition governed by Raiden Ei's pursuit of a changeless future.",
  "Sumeru": "Sumeru is the nation of wisdom, spanning rainforest and desert, where the Akademiya and Lesser Lord Kusanali shape knowledge and dreams.",
  "Fontaine": "Fontaine is the nation of justice, where court trials, performance and prophecy expose the hidden cost of Iudex Neuvillette's rule.",
  "Natlan": "Natlan is the nation of Pyro, organized around tribal nations, the Sacred Flame and the Night Kingdom's long struggle against the Abyss.",
  "Nod-Krai": "Nod-Krai is a contested frontier south of Snezhnaya, where moon-linked factions, the Lightkeepers and the Fatui meet on Teyvat's northern edge.",
  "Snezhnaya": "Snezhnaya is the Cryo nation of the Tsaritsa, where the Fatui advance a national plan opposed to the present divine order.",
  "Khaenri'ah": "Khaenri'ah was a human kingdom destroyed during Teyvat's cataclysm, preserved today through forbidden knowledge, the Abyss and its surviving descendants."
};

const notableProfiles: Record<string, { role: string; biography: string; powers: string }> = {
  "Amber": { role:"Outrider · Knights of Favonius", biography:"The only remaining Outrider of the Knights of Favonius, Amber is the first to meet the Traveler at Mondstadt's gates and the last to retreat when the city is threatened. Her optimism is not naivety — it coexists with sharp field awareness, genuine combat capability and a commitment to protecting the city that has never required anyone's approval to sustain.", powers:"Pyro archery, Baron Bunny decoy detonations and rapid gliding reconnaissance." },
  "Albedo": { role:"Chief Alchemist · Kreideprinz", biography:"Created through the ancient technique of Khemia by the master alchemist Rhinedottir, Albedo serves as the Knights of Favonius' Chief Alchemist while conducting private research into the boundary of his own artificial existence. The question that drives his work — whether artificial life and natural life are meaningfully distinct — is not merely philosophical; it is the central fact of who he is.", powers:"Geo swordsmanship and Solar Isotoma transmutation fields." },
  "Diluc": { role:"Dawn Winery · Unofficial Protector", biography:"Once the youngest Knight of Favonius ever to reach the rank of Captain, Diluc left the organization after witnessing both a Fatui operative's actions and the institution's unwillingness to hold itself accountable for the consequences. He now operates entirely outside official channels — running Dawn Winery, funding an intelligence network and protecting Mondstadt through means the Knights have never sanctioned and cannot attribute to him.", powers:"Claymore combat with concentrated Pyro energy and Dawn's fire." },
  "Jean": { role:"Acting Grand Master · Knights of Favonius", biography:"The person who actually keeps Mondstadt's governing institution functional — Jean manages daily operations, international diplomacy, internal discipline and emergency response with a personal sense of duty so extensive that rest has become an afterthought. Her skill as a leader is real and her care for the city genuine, but the weight she carries rarely lightens and she rarely asks anyone to help carry it.", powers:"Sword combat and Anemo healing — the Dandelion Breeze recovers the entire party." },
  "Lisa": { role:"Knights Librarian · Witch", biography:"A veteran Electro mage who left the Sumeru Akademiya — where she was considered one of its most brilliant graduates — in favor of a quieter, apparently less ambitious life as the Knights of Favonius' librarian. Lisa watches Mondstadt from behind a measured, amused calm that conceals how much she observes and how little she chooses to involve herself with. The choice to stay in the library is entirely deliberate.", powers:"Electro spellcasting, chained rune detonations and the Rose Garden curse." },
  "Klee": { role:"Spark Knight · Knights of Favonius", biography:"Alice's daughter, left in the Knights of Favonius' care while her mother pursues expeditions across Teyvat. Klee's approach to obstacles is consistent regardless of category — fish, monsters, rocks and inconvenient geography all receive explosive solutions. Her confinement in the Knights' prison library is a recurring outcome of that consistency and has never appeared to diminish her enthusiasm for the next attempt.", powers:"Catalyst Pyro bombs, Jumpy Dumpty mines and the Sparks 'n' Splash burst." },
  "Ganyu": { role:"Qixing Secretary · Half-Qilin Adeptus", biography:"A half-human, half-Qilin Adeptus who has served as mediator and secretary between the Liyue Qixing and the Adepti for three thousand years. Ganyu's centuries of absorbing others' expectations — both human and divine — have left her deeply conscientious and quietly exhausted. She measures her worth in what she can do for others and rarely considers what she might actually want for herself.", powers:"Cryo bow combat, adeptal charged shot bloom attacks and Sacred Cryo Pearl Celestia." },
  "Hu Tao": { role:"Director · Wangsheng Funeral Parlor", biography:"The 77th Director of Wangsheng Funeral Parlor who approaches death not as a tragedy but as a ceremony — a transition that deserves to be handled with the same care and intention as any other significant event in a life. Hu Tao's theatrical manner is genuine rather than performative. She has thought about mortality more carefully than most people twice her age and her comfort with it is the product of that thought.", powers:"Polearm combat with Pyro vitality exchange — Guide to Afterlife converts HP into Pyro attack power." },
  "Keqing": { role:"Yuheng · Liyue Qixing", biography:"The Yuheng of the Liyue Qixing who fundamentally disputes the idea that a nation should depend on its gods for governance, direction or rescue. Keqing's work is built on the principle that people are capable of solving their own problems, and her frustration with Rex Lapis has driven her to become, arguably, the most practically effective reformer in Liyue's public administration.", powers:"Electro sword teleportation, rapid Stellar Restoration slashes and Starward Sword." },
  "Raiden Shogun": { role:"Electro Archon · Eternity", biography:"Raiden Ei governs Inazuma through a puppet body she created to administer the Vision Hunt Decree while she meditates in the Plane of Euthymia — a divine space where time and change cannot reach her. Ei's pursuit of eternity is rooted in the losses of the Archon War: she watched friends and siblings die and concluded that protection requires preventing change. The Traveler's confrontation with her becomes a conversation about whether stillness and death are, finally, different things.", powers:"Electro polearm authority, Musou Isshin divine blade and the Plane of Euthymia." },
  "Yae Miko": { role:"Guuji · Grand Narukami Shrine", biography:"The Guuji of the Grand Narukami Shrine — a kitsune whose history predates most of Inazuma's current institutions — manages the shrine, runs the Yae Publishing House and maintains her friendship with Ei through the Plane of Euthymia. Yae Miko periodically tests the limits of the Shogun's decisions, not from disloyalty but from a conviction that people, including gods, should encounter the consequences of their choices.", powers:"Electro catalyst spells, Sesshou Sakura kitsune familiars and the Great Secret Art." },
  "Kaedehara Kazuha": { role:"Wandering Samurai · Crux Fleet", biography:"A wandering samurai of the disgraced Kaedehara clan who witnessed a close friend die under the Vision Hunt Decree — struck down trying to claim a fallen Vision — and has since carried his friend's Vision alongside his grief and the blade of a dissolved tradition. Kazuha reads the wind, the emotions of people around him and the meaning of moments with a sensitivity he has never found reason to suppress or explain.", powers:"Anemo sword techniques, wind-infused strikes, Chihayaburu Midare Ranzan and plunge combos." },
  "Kamisato Ayato": { role:"Yashiro Commission · Kamisato Clan Head", biography:"The head of the Kamisato Clan who manages the household's political position through commerce, alliance-building and extremely careful management of what other factions believe the Kamisatos want. Ayato's relaxed demeanor during tense situations is not indifference — it reflects extensive preparation and a talent for understanding what other people are trying to accomplish well before they reveal it.", powers:"Hydro sword phantoms, rapid Kamisato Art: Suiyuu blade sequence and Kamisato Art: Kami Nomi." },
  "Kirara": { role:"Nekomata Courier · Komaniya Express", biography:"A nekomata courier who approaches every delivery as a solemn professional obligation. Kirara's knowledge of Inazuma's roads, weather patterns and island-to-island routes is detailed enough to be valuable on its own, but what actually distinguishes her is the pride she takes in keeping every promise to every client — a commitment that extends to genuinely dangerous situations without hesitation.", powers:"Dendro swordwork, fleet-footed Urgent Neko Parcel transport and protective Jadefall Shield barriers." },
  "Kujou Sara": { role:"Tenryou Commission · Tengu General", biography:"A tengu general raised to serve Inazuma through absolute discipline, whose loyalty to the Raiden Shogun has survived doubt, loss and the realization that obedience can conceal injustice. Sara's confrontation with the gap between loyalty and justice does not resolve quickly — and the resolution requires her to hold both simultaneously rather than discarding the one that became inconvenient.", powers:"Electro bow attacks, Tengu ambush tactics and Crowfeather Marks that empower allies." },
  "Kuki Shinobu": { role:"Arataki Gang · Deputy and Exorcist", biography:"Itto's deputy and the reason the Arataki Gang has any operational coherence at all. Shinobu holds academic qualifications in law, shrine practice and practical medicine — credentials she obtained partly to give herself options. She joined the gang by genuine choice and remains not because she lacks alternatives but because she has decided these people deserve someone capable of looking after them.", powers:"Electro sword combat, Sanctifying Ring healing and Ninjutsu: Gyoei Narukami Kariyama Hito." },
  "Sangonomiya Kokomi": { role:"Watatsumi Island · Divine Priestess", biography:"The Divine Priestess who simultaneously leads Watatsumi Island's military strategy, civil administration and religious ceremonies — a workload she carries with careful preparation and the quiet awareness that her talent for strategy sometimes isolates her from the people she is protecting. Kokomi deliberately avoids cultivating personal fame, preferring outcomes to recognition.", powers:"Hydro catalyst attacks, restorative Nereid's Ascension formations and tactical healing buffs." },
  "Sayu": { role:"Shuumatsuban · Ninja", biography:"A ninja who is convinced the secret to growing taller is to sleep as much as possible and has organized her entire professional life around protecting opportunities for rest. Sayu is genuinely capable — her stealth, speed and momentum-based combat reflect real discipline — but she prefers to conserve energy for missions and considers excessive wakefulness a poor use of a person's limited time.", powers:"Anemo claymore attacks, Yoohoo Art: Fuuin Dash and restorative Mujina Flurry ninja techniques." },
  "Nahida": { role:"Dendro Archon · Lesser Lord Kusanali", biography:"The Dendro Archon of Sumeru who has been confined in the Sanctuary of Surasthana by the Grand Sages for nearly five hundred years. Despite her isolation from the physical world, Nahida observed Sumeru through its dreams and the Akasha System with patience and genuine care — developing a deep understanding of its people while they were taught to dismiss her as an inadequate god. When the Traveler reaches her, she finally has a way to act.", powers:"Dendro dream entry, All Schemes to Know shared perception and Illusory Heart elemental authority." },
  "Furina": { role:"Former Hydro Archon · Performer", biography:"Given the role of Focalors and left to perform it without divine power for five hundred years, Furina maintained Fontaine's court, withstood its trials and endured public mockery as an apparently fallible god — all to satisfy the conditions of a plan she was never permitted to explain. The plan worked. The prophecy was defeated. Furina survived to discover that the performance she spent her entire life perfecting was the most selfless act anyone in Teyvat has done alone.", powers:"Hydro performance, Salon Members summoning, Le Grand Finale burst and dramatic elemental control." },
  "Neuvillette": { role:"Iudex · Hydro Dragon Sovereign", biography:"The Iudex of Fontaine whose composed judicial authority has governed its Court for centuries. Neuvillette is the reincarnation of the Hydro Dragon Sovereign — one of the original rulers of Teyvat before the Archons — who has been slowly reclaiming the authority lost during the ancient conflict. His visible grief at Fontaine's sorrows is not performance: the rain that falls when he cries is real.", powers:"Hydro sovereign attacks, Equitable Judgment charged torrents and Dragon Sovereign authority." },
  "Mavuika": { role:"Pyro Archon · Sun Bearer", biography:"The Pyro Archon who carries the Sacred Flame on behalf of Natlan's tribes, mediates between their competing traditions and has known for some time that the current cycle of the Night Kingdom war will require a final cost she is prepared to pay. Mavuika's warmth toward the people of Natlan is not performance — it is the product of centuries spent in genuine relationship with them, coexisting with a clear-eyed understanding of what protecting them has always required.", powers:"Pyro authority, Flamestrider combat mode and the Ring of Searing Radiance coordinated burst." },
  "Columbina Hyposelenia": { role:"Former Fatui Harbinger · Moon-linked figure", biography:"A former Fatui Harbinger whose connection to the moon, the Abyss and forces that extend beyond Snezhnaya's known operations makes her one of the most significant presences in Nod-Krai's story. Columbina's nature, motivations and the full scope of her power remain deliberately obscured — she operates at the edge of what the archive can confirm and the beginning of something the Traveler has not yet fully encountered.", powers:"Moon-linked elemental manipulation and elusive supernatural power beyond conventional classification." },
  "Arlecchino": { role:"Fourth Fatui Harbinger · The Knave", biography:"The Fourth Fatui Harbinger who leads the House of the Hearth — an orphanage and training operation that raises Fatui operatives from childhood through a system of Blood-Debt that obligates every member until cleared. Arlecchino's goals are not identical to the Fatui's conventional interests, her method of running the House differs from its history, and her understanding of what she is building becomes clear only when the Traveler encounters what the House's members will actually do for her.", powers:"Pyro scythe combat, Blood-Debt Directive marks and All is Ash sovereign Pyro authority." },
  "Tartaglia": { role:"Eleventh Fatui Harbinger · Childe", biography:"The Eleventh Fatui Harbinger known as Childe whose defining characteristic is a desire for combat that has shaped his entire history — including the discovery of the Foul Legacy fighting style in an Abyssal space he entered as a child and was changed by permanently. Tartaglia's campaigns across nations are not simply Fatui operations; they are his own search for opponents and situations that can fully engage what he has become.", powers:"Hydro bow and melee Foul Legacy transformation — Riptide cycling between ranged and close combat." },
  "Lauma": { role:"Frostmoon Scions · Moonchant leader", biography:"The emissary and leader of the Frostmoon Scions who defends her community's lunar traditions from exploitation while navigating pressure from the Fatui and the broader destabilization that the Song of the Welkin Moon crisis brings to Nod-Krai's fragile autonomy. Lauma connects the Traveler to Nod-Krai's oldest supernatural inheritances.", powers:"Dendro lunar ritual combat and moon-linked elemental channeling." },
  "Flins": { role:"Lightkeeper · Nod-Krai", biography:"A Lightkeeper stationed at one of Nod-Krai's northern frontier posts who monitors the region's supernatural phenomena and maintains the defensive infrastructure that has kept its communities separated from whatever the region's ancient history contains. Flins connects the Traveler to the Lightkeepers' institutional knowledge and the personal experience of a frontier where ordinary danger and something much older are never entirely separate.", powers:"Electro polearm combat and Lightkeeper monitoring authority." },
  "Aino": { role:"Mechanic · Clink-Clank Krumkake", biography:"A young inventor at Nod-Krai's Clink-Clank Krumkake Craftshop whose practical engineering approaches the region's unusual frontier problems with curiosity rather than ideology. Aino has built machines that account for the moon's influence on Nod-Krai's materials and geography — a design challenge that no craftsman outside the region has had reason to solve.", powers:"Hydro machinery and mechanical field coordination." }
};

function detailedBackground(name: string, region: string, quest: string) {
  const notable = notableProfiles[name];
  if (notable) return `${notable.biography}`;
  const fact = characterFacts[name];
  if (fact) return `${fact.story}`;
  return `${name} is a figure connected to ${region}'s people and the events of ${quest}. Their role in the region's story is recorded in the archive through their ${region} identity, regional affiliations and combat profile.`;
}

